class Solution:
    def uniqueLetterString(self, s: str) -> int:
        n, ans = len(s), 0
        for i in range(n):
            cnt = [0] * 26
            uniq = 0
            for j in range(i, n):
                c = ord(s[j]) - 65
                cnt[c] += 1
                if cnt[c] == 1:
                    uniq += 1
                elif cnt[c] == 2:
                    uniq -= 1
                ans += uniq
        return ans

