class Solution {
public:
    int uniqueLetterString(string s) {
        long long ans = 0;
        int n = s.size();
        for (int i = 0; i < n; i++) {
            int cnt[26] = {0}, uniq = 0;
            for (int j = i; j < n; j++) {
                int c = s[j] - 'A';
                if (++cnt[c] == 1) uniq++;
                else if (cnt[c] == 2) uniq--;
                ans += uniq;
            }
        }
        return (int)ans;
    }
};

