class Solution:
    def uniqueLetterString(self, s: str) -> int:
        n = len(s)
        prev = [-1] * n
        nxt = [n] * n
        last = {}
        for i, ch in enumerate(s):
            if ch in last:
                prev[i] = last[ch]
            last[ch] = i
        last = {}
        for i in range(n - 1, -1, -1):
            if s[i] in last:
                nxt[i] = last[s[i]]
            last[s[i]] = i
        return sum((i - prev[i]) * (nxt[i] - i) for i in range(n))

