class Solution {
public:
    int uniqueLetterString(string s) {
        int n = s.size();
        vector<int> prev(n, -1), nxt(n, n);
        vector<int> last(26, -1);
        for (int i = 0; i < n; i++) {
            prev[i] = last[s[i] - 'A'];
            last[s[i] - 'A'] = i;
        }
        fill(last.begin(), last.end(), -1);
        for (int i = n - 1; i >= 0; i--) {
            int &l = last[s[i] - 'A'];
            if (l != -1) nxt[i] = l;
            l = i;
        }
        long long ans = 0;
        for (int i = 0; i < n; i++)
            ans += (long long)(i - prev[i]) * (nxt[i] - i);
        return (int)ans;
    }
};

