class Solution {
    public int uniqueLetterString(String s) {
        int n = s.length();
        int[] prev = new int[n], nxt = new int[n];
        int[] last = new int[26];
        Arrays.fill(last, -1);
        for (int i = 0; i < n; i++) {
            prev[i] = last[s.charAt(i) - 'A'];
            last[s.charAt(i) - 'A'] = i;
        }
        Arrays.fill(last, -1);
        for (int i = n - 1; i >= 0; i--) {
            int c = s.charAt(i) - 'A';
            nxt[i] = (last[c] == -1) ? n : last[c];
            last[c] = i;
        }
        long ans = 0;
        for (int i = 0; i < n; i++)
            ans += (long)(i - prev[i]) * (nxt[i] - i);
        return (int) ans;
    }
}

